const PAYMENT_PROCESSOR_ID = 92690421680; 
const INACTIVITY_DELAY_MS = 1000 * 60 * 5; // 5 minutos
const COLLECTION_TIME_MS = 10 * 60 * 1000; // 10 minutos

class CartClass {
    /**
     * @param {import('discord.js').Client} client 
     * @param {Interaction} interaction 
