        this.channel = null;
        this.quantity = 1;
        this.selectedPlan = null;
        this.days = 0; // Definido dinamicamente
        this.message = null; // Armazena o Message object do Discord
        this.paymentId = null; // ID do pagamento (crucial para cancelamento)
        this.inactivityDelay = INACTIVITY_DELAY_MS;
    }

    // --- UTILITIES ---

