    cratePlanItens = () => {
        const { preco } = this.productData;
        // Verifica se o plano está selecionado antes de calcular o total
        if (!this.selectedPlan || !preco[this.selectedPlan] || !preco[this.selectedPlan].preco) {
            return { embeds: [new EmbedBuilder().setDescription("Erro: Plano não selecionado.")], components: [] };
        }

        const total = Number(preco[this.selectedPlan].preco * this.quantity).toFixed(2);

        const embed = new EmbedBuilder()
            .setDescription(`### Olá, ${this.user.tag}! Seja bem-vindo(a) ao seu carrinho\n-# Você está prestes a adquirir o ${this.productData.productName}, um sistema exclusivo da **Nyox Applications** com a melhor qualidade de mercado.`
                + `\n`
                + `\n\`📦\` **Produto**: ${this.productData.productName}`
                + `\n\`✨\` **Plano**: ${this.capitalize(this.selectedPlan)} (x${this.quantity}) - ${this.days} dias`
                + `\n\`💰\` **Valor**: R$${total}`
            )
            .setColor("#060A18");

        const buttonsRow = new ActionRowBuilder().addComponents(
            new ButtonBuilder().setCustomId("addToCart").setLabel("➕").setStyle(ButtonStyle.Primary),
            new ButtonBuilder().setCustomId("removeFromCart").setLabel("➖").setStyle(ButtonStyle.Secondary),
            new ButtonBuilder().setCustomId("finalizePurchase").setLabel("Confirmar Pedido").setStyle(ButtonStyle.Success).setEmoji("✅"),
            new ButtonBuilder().setCustomId("cancelOrder").setLabel("Cancelar Pedido").setStyle(ButtonStyle.Danger).setEmoji("❌")
        );

        return { embeds: [embed], components: [buttonsRow] };
    };

    // --- TIMERS ---

    setInactivityTimer = (callback) => {
        if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
        this.inactivityTimer = setTimeout(callback, this.inactivityDelay);
    };

    // --- HANDLERS DE ESTADO ---

    handleInactivity = async () => {
        try {
            await this.user.send({ embeds: [this.createInactivityEmbed()] });

            const logEmbed = new EmbedBuilder()
                .setTitle("Sistema de Logs - Inatividade")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild.name, iconURL: this.interaction.guild.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 | Usuário:', value: `${this.user.tag} - \`${this.user.id}\`` },
                    { name: '📝 | Carrinho Fechado:', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '🕒 | Data / Horário do Fechamento:', value: `<t:${Math.floor(Date.now() / 1000)}:f>` },
                    { name: '❔ | Motivo:', value: `Inatividade` }
                );

            await this.sendLog(logEmbed);

            if (this.channel) {
                await Cart.deleteOne({ channelId: this.channel.id });
                // Delete o canal, mas é bom tratar erro aqui
                await this.channel.delete().catch(e => console.error("Erro ao deletar canal:", e)); 
            }
        } catch (error) {
            console.error("Erro ao lidar com inatividade:", error);
        }
    };

    handleApprovedPayment = async (paymentId) => {
        try {
            const cart = await Cart.findOne({ channelId: this.channel.id });
            if (!cart || cart.status !== "Aguardando...") return;

            cart.status = "Processando";
            await cart.save();

            const member = this.interaction.guild.members.cache.get(this.user.id);
            if (member && CARGO_CLIENT_ID) {
                await member.roles.add(CARGO_CLIENT_ID).catch(() => console.log("Usuário já possui o cargo ou erro de permissão."));
            }

            // Limpeza e Mensagem de Sucesso
            await this.channel.bulkDelete(50).catch(e => console.warn("Não foi possível deletar mensagens antigas:", e));
            await this.channel.send({ content: `✅ Pagamento Aprovado \n🆔 ID da Compra: ${this.cartId}` });

            // Mensagem de entrega de bot
            await this.channel.send({
                content: `${this.user}`,
                embeds: [
                    new EmbedBuilder()
                        .setTitle("Pagamento Aprovado")
                        .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                        .setDescription(`**O pagamento foi aprovado! Para enviar o seu bot, preciso de algumas informações:**\n\n- **Nome que você irá querer na aplicação**\n- **ID que será setado como dono do bot**\n- **Token do Bot**\n\n**⚠ | Mantenha o token do bot seguro. Não compartilhe com ninguém!**`)
                ],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder().setLabel("Enviar Bot").setEmoji("🎉").setStyle(ButtonStyle.Primary).setCustomId(`${this.selectedPlan}_${this.days * this.quantity}_${this.productId}_redeemBot`),
                        new ButtonBuilder().setLabel("Portal Desenvolvedor").setEmoji("🤖").setStyle(ButtonStyle.Link).setURL("https://discord.com/developers/applications/"),
                        new ButtonBuilder().setLabel("Tutorial").setEmoji("🔗").setStyle(ButtonStyle.Link).setURL("https://docs.nyox.tech/tutorials/createapp")
                    )
                ]
            });
        } catch (error) {
            console.error("Erro ao lidar com pagamento aprovado:", error);
        }
    };

    /**
     * Lida com a criação e processamento do pagamento
     * @param {Object} paymentResponse Retorno da criação do pagamento
     */
    processPayment = async (paymentResponse) => {
        try {
            if (!paymentResponse) throw new Error("Resposta de pagamento inválida.");

            const { id, attachment, pixCopyPasteCode } = paymentResponse;
            this.paymentId = id; // Armazena o ID do pagamento
            console.log(`[Payment] - Pagamento criado com sucesso (${id})`);

            const totalAmount = Number(this.productData.preco[this.selectedPlan].preco * this.quantity).toFixed(2);

            // Atualiza a mensagem existente (o cartão do carrinho)
            await this.message.edit({
                embeds: [
                    new EmbedBuilder().setDescription("### Resumo do Carrinho"
                        + `\n\`📨\` **ID**: ${this.cartId}`
                        + `\n\`📦\` **Produto**: ${this.productData.productName}`
                        + `\n\`✨\` **Plano**: ${this.capitalize(this.selectedPlan)} (x${this.quantity}) - ${this.days * this.quantity} dias`
                        + `\n\`💸\` **Total**: R$${totalAmount}`
                    ),
                    new EmbedBuilder().setDescription("- **Pague o Pix via QR CODE ou código pix abaixo**\n- O pagamento será verificado automaticamente\n- Expira em <t::R>")
                        .setImage(`attachment://qrcode.png`)
                ],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder().setCustomId("pixCopyPaste").setLabel("Código copia e cola").setEmoji("💰").setStyle(ButtonStyle.Secondary),
                        new ButtonBuilder().setCustomId("cancelPayment").setLabel("Cancelar Pedido").setStyle(ButtonStyle.Danger)
                    )
                ]
            });

            if (attachment) {
                await this.channel.send({ files: [attachment] });
            }

            // Monitoramento do status do pagamento
            const checkPaymentStatus = setInterval(async () => {
                try {
                    // Idealmente, use o PaymentProcessor para checar o status
                    // const status = await this.paymentProcessor.checkPaymentStatus(id);
                    const status = 'approved'; // SIMULAÇÃO

                    console.log(`[Payment] - Status do pagamento (${id}): ${status}`);

                    if (status === "approved") {
                        clearInterval(checkPaymentStatus);
                        await this.handleApprovedPayment(id);
                    } else if (status === "cancelled") {
                        clearInterval(checkPaymentStatus);
                        await this.handleInactivity(); // Trata cancelamento externo
                    }
                } catch (error) {
                    console.error("Erro ao verificar status do pagamento:", error);
                }
            }, 60000); 

        } catch (error) {
            console.error("Erro ao processar pagamento:", error);
            // Feedback para o usuário
            if (this.interaction) {
                await this.interaction.reply({ content: "Ocorreu um erro ao iniciar o processo de pagamento. Tente novamente.", ephemeral: true });
            }
        }
    };

    // --- FLUXOS DE COMPRA ---

    handlePlanSelection = async (interaction, forcePlan) => {
        const planKeys = {
            "7DiasCart": "semanal",
            "15DiasCart": "quizena",
            "30DiasCart": "mensal"
        };

        const planKey = forcePlan || planKeys[interaction.customId];

        if (!planKey) return;

        this.selectedPlan = planKey;
        this.days = this.productData.preco[planKey].onoff ? (planKey === 'semanal' ? 7 : planKey === 'quizena' ? 15 : 30) : 0;

        // Atualiza o DB
        await Cart.findOneAndUpdate(
            { channelId: this.channel.id },
            { quantity: this.quantity, status: "Aguardando...", selectedPlan: this.selectedPlan },
            { new: true }
        );

        // Atualiza a mensagem de carrinho
        await this.message.edit(this.cratePlanItens());

        // Log de criação do carrinho
        const logEmbed = new EmbedBuilder()
            .setTitle("📝 Sistema de Logs - Carrinho Criado")
            .setColor("#FF4500")
            .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
            .addFields(
                { name: "👥 Usuário", value: `${this.user.tag} - \`${this.user.id}\``, inline: false },
                { name: "🛒 Carrinho", value: `Produto: **${this.productData.productName}** - \`${this.cartId}\``, inline: false },
                { name: "🕒 Data", value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)`, inline: false }
            );
        await this.sendLog(logEmbed);

        // Reinicia o timer de inatividade
        this.setInactivityTimer(() => this.handleInactivity());
    };

    finalizePurchase = async (interaction) => {
        try {
            clearTimeout(this.inactivityTimer);

            const { preco } = this.productData;
            const plan = preco[this.selectedPlan];

            if (!plan || !plan.preco) throw new Error("Plano inválido ou preço ausente.");

            const totalAmount = Number(plan.preco * this.quantity).toFixed(2);

            const paymentOptions = {
                amount: totalAmount,
                description: `Saldo - ${this.user.tag}`,
                first_name: this.user.firstName || 'Cliente',
                email: this.user.email || 'paymentsinbox@nyox.tech',
                otherData: {
                    notification_url: "https://nyox.tech/api/notifications"
                }
            };

            // 1. Cria o pagamento
            const paymentResponse = await this.paymentProcessor.getPayment(PAYMENT_PROCESSOR_ID);

            await interaction.deferUpdate();

            if (!paymentResponse || !paymentResponse.id) throw new Error("Falha ao criar o pagamento.");

            // 2. Salva no DB
            const payment = new Payment({
                payment_id: paymentResponse.id,
                transaction_amount: totalAmount,
                description: paymentOptions.description,
                customerId: this.user.id,
                email: paymentOptions.email
            });
            await payment.save();
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { paymentId: paymentResponse.id, status: "Aguardando..." },
                { new: true }
            );

            // 3. Processa (atualiza UI e monitora status)
            await this.processPayment(paymentResponse);

        } catch (error) {
            console.error("Erro ao finalizar pedido:", error);
            if (interaction) {
                await interaction.editReply({ content: `❌ Ocorreu um erro ao processar seu pedido: ${error.message}. Por favor, tente novamente mais tarde.`, ephemeral: true });
            }
        }
    };

    updateCartQuantity = async (interaction, action) => {
        try {
            let newQuantity = this.quantity;
            if (action === "add") {
                newQuantity += 1;
            } else if (action === "remove") {
                newQuantity -= 1;
                if (newQuantity < 1) return interaction.reply({ embeds: [new EmbedBuilder().setDescription("❌ | Você não pode diminuir mais.")], ephemeral: true });
            }

            this.quantity = newQuantity;

            // Atualiza o DB
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { quantity: this.quantity },
                { new: true }
            );

            // Atualiza a mensagem
            await interaction.update(this.cratePlanItens());

            // Reinicia o timer de inatividade
            this.setInactivityTimer(() => this.handleInactivity());
        } catch (error) {
            console.error("Erro ao atualizar quantidade do carrinho:", error);
            if (interaction) {
                await interaction.reply({ content: "Erro ao atualizar a quantidade. Tente novamente.", ephemeral: true });
            }
        }
    };

    handleCancellation = async (interaction) => {
        try {
            const logEmbed = new EmbedBuilder()
                .setTitle("Sistema de Logs - Cancelamento")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 Usuário', value: `${this.user.tag} - \`${this.user.id}\`` },
                    { name: '📝 Carrinho', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '🕒 Data', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)` },
                    { name: '❔ Motivo', value: `Cancelado pelo usuário.` }
                );

            await this.sendLog(logEmbed);

            if (this.channel) {
                await Cart.deleteOne({ channelId: this.channel.id });
                await this.channel.delete().catch(e => console.error("Erro ao deletar canal após cancelamento:", e));
            }
        } catch (error) {
            console.error("Erro ao lidar com cancelamento:", error);
        }
    };

    handleCancelPayment = async (interaction) => {
        try {
            const logEmbed = new EmbedBuilder()
                .setTitle("Sistema de Logs - Pagamento Cancelado")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 Usuário', value: `${this.user.tag} - \`${this.user.id}\`` },
                    { name: '📝 Carrinho', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '❔ Motivo', value: `Pagamento cancelado pelo usuário.` },
                    { name: '🕒 Data', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)` }
                );

            await this.sendLog(logEmbed);

            if (this.paymentId) {
                // Tenta cancelar o pagamento antes de limpar o carrinho
                await this.paymentProcessor.cancelPayment(this.paymentId); 
            }

            if (this.channel) {
                await Cart.deleteOne({ channelId: this.channel.id });
                await this.channel.delete().catch(e => console.error("Erro ao deletar canal após cancelamento de pagamento:", e));
            }
        } catch (error) {
            console.error("Erro ao cancelar pagamento:", error);
        }
    };


    // --- FLUXO PRINCIPAL ---

    createCart = async () => {
        try {
            // 1. Verifica carrinho existente
            const existingCart = await Cart.findOne({ userId: this.user.id });
            if (existingCart) {
                const guildChannel = this.client.channels.cache.get(existingCart.channelId);
                if (guildChannel) {
                    this.channel = guildChannel;
                    this.cartId = existingCart.id;
                    this.quantity = existingCart.quantity;
                    this.selectedPlan = existingCart.selectedPlan;

                    // Determina dias com base no plano salvo
                    const planDuration = existingCart.selectedPlan === "mensal" ? 30 : existingCart.selectedPlan === "quizena" ? 15 : 7;
                    this.days = planDuration;

                    return this.interaction ? this.interaction.reply(this.createCartOpenEmbed(guildChannel)) : true;
                }
            }

            await this.interaction.reply({ content: "Aguarde um momento, estou criando seu carrinho...", ephemeral: true });

            // 2. Cria o Thread/Canal
            const thread = await this.interaction.channel.threads.create({
                name: `🛒・${this.user.username}・${this.user.id}`,
                topic: `Carrinho de Compras - ${this.productData.productName} - ${this.cartId}`,
                autoArchiveDuration: 60,
                type: ChannelType.PrivateThread,
                reason: "Criação de carrinho de compras",
                members: [this.user.id],
                permissionOverwrites: [
                    { id: this.user.id, allow: ["ViewChannel"], deny: ["SendMessages"] }, // Permite ver, mas não interage inicialmente
                    { id: this.interaction.guild.id, deny: ["ViewChannel", "SendMessages"] } // Esconde de todos
                ]
            });

            this.channel = thread;

            // 3. Salva no DB
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                {
                    userId: this.user.id,
                    quantity: this.quantity,
                    cartId: this.cartId,
                    productId: this.productId,
                    status: "Aguardando..."
                },
                { upsert: true, new: true }
            );

            // 4. Define o timer e envia mensagem
            this.setInactivityTimer(() => this.handleInactivity());
            await this.interaction.editReply(this.createCartSuccessEmbed(this.channel.url));

            const initialEmbed = this.createPlanSelectionEmbed();
            this.message = await this.channel.send(initialEmbed);

            // 5. Seleciona um plano padrão para iniciar o fluxo
            await this.handlePlanSelection(this.interaction, "30DiasCart"); 
        } catch (error) {
            console.error("Erro fatal ao criar carrinho:", error);
            if (this.interaction) {
                await this.interaction.editReply({ content: "❌ Ocorreu um erro ao iniciar o carrinho. Verifique os logs do bot.", ephemeral: true });
            }
        }
    };

    /**
     * Inicia o processo do carrinho
     */
    run = async () => {
        await this.createCart();

        // Listener para interações dentro do carrinho
        const collector = this.channel.createMessageComponentCollector({ componentType: ComponentType.Button, time: COLLECTION_TIME_MS });

        collector.on("collect", async (btnInteraction) => {
            // Garante que a interação veio do usuário correto
            if (btnInteraction.user.id !== this.user.id) {
                await btnInteraction.deferUpdate();
                return;
            }

            clearTimeout(this.inactivityTimer);
            this.interaction = btnInteraction; // Atualiza a referência de interação

            // Reinicia o timer em todas as interações válidas
            this.setInactivityTimer(() => this.handleInactivity());

            try {
                switch (btnInteraction.customId) {
                    case "7DiasCart":
                    case "15DiasCart":
                    case "30DiasCart":
                        await btnInteraction.deferUpdate();
                        await this.handlePlanSelection(btnInteraction);
                        break;

                    case "cancelOrder":
                        await this.handleCancellation(btnInteraction);
                        break;

                    case "addToCart":
                        await this.updateCartQuantity(btnInteraction, "add");
                        break;

                    case "removeFromCart":
                        await this.updateCartQuantity(btnInteraction, "remove");
                        break;

                    case "finalizePurchase":
                        await this.finalizePurchase(btnInteraction);
                        break;

                    case "pixCopyPaste":
                    case "qrCode":
                        await this.sendPaymentDetails(btnInteraction);
                        break;

                    case "cancelPayment":
                        await this.handleCancelPayment(btnInteraction);
                        break;

                    default:
                        console.log(`Custom ID desconhecido: ${btnInteraction.customId}`);
                }
            } catch (e) {
                console.error(`Erro durante a coleta de interação (${btnInteraction.customId}):`, e);
                if (btnInteraction.replied || btnInteraction.deferred) {
                    await btnInteraction.followUp({ content: "⚠️ Ocorreu um erro ao processar esta ação. Tente novamente.", ephemeral: true });
                } else {
                    await btnInteraction.reply({ content: "⚠️ Ocorreu um erro ao processar esta ação. Tente novamente.", ephemeral: true });
                }
            }
        });

        collector.on("end", () => {
            if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
            console.log("Colecionador de interações do carrinho finalizado.");
        });
    };

    /**
     * Função auxiliar para obter e enviar detalhes de pagamento
     */
    async sendPaymentDetails = async (interaction) => {
        try {
            const cart = await Cart.findOne({ channelId: this.channel.id });
            if (cart && cart.paymentId) {
                const paymentDetails = await this.paymentProcessor.getPayment(cart.paymentId);

                if (!paymentDetails) {
                    await interaction.reply({ content: "Detalhes de pagamento não encontrados.", ephemeral: true });
                    return;
                }

                if (interaction.customId === "qrCode" && paymentDetails.attachment) {
                    await interaction.reply({ files: [paymentDetails.attachment], ephemeral: true });
                } else if (interaction.customId === "pixCopyPaste" && paymentDetails.pixCopyPasteCode) {
                    await interaction.reply({ content: paymentDetails.pixCopyPasteCode, ephemeral: true });
                } else {
                     await interaction.reply({ content: "Detalhes de pagamento incompletos.", ephemeral: true });
                }
            } else {
                await interaction.reply({ content: "Pagamento não iniciado ou não encontrado.", ephemeral: true });
            }
        } catch (error) {
            console.error("Erro ao enviar detalhes do pagamento:", error);
            await interaction.reply({ content: "Ocorreu um erro ao obter os detalhes do pagamento. Tente mais tarde.", ephemeral: true });
        }
    };
}

module.exports = CartClass;
