                    notification_url: "https://nyox.tech/api/notifications"
                }
            };

            // 1. Cria o pagamento
            const paymentResponse = await this.paymentProcessor.getPayment(PAYMENT_PROCESSOR_ID);

            await interaction.deferUpdate();

            if (!paymentResponse || !paymentResponse.id) throw new Error("Falha ao criar o pagamento.");

            // 2. Salva no DB
            const payment = new Payment({
                payment_id: paymentResponse.id,
                transaction_amount: totalAmount,
                description: paymentOptions.description,
                customerId: this.user.id,
                email: paymentOptions.email
            });
            await payment.save();
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { paymentId: paymentResponse.id, status: "Aguardando..." },
                { new: true }
            );

            // 3. Processa (atualiza UI e monitora status)
            await this.processPayment(paymentResponse);

        } catch (error) {
            console.error("Erro ao finalizar pedido:", error);
            if (interaction) {
                await interaction.editReply({ content: `❌ Ocorreu um erro ao processar seu pedido: ${error.message}. Por favor, tente novamente mais tarde.`, ephemeral: true });
            }
        }
    };

    updateCartQuantity = async (interaction, action) => {
        try {
            let newQuantity = this.quantity;
            if (action === "add") {
                newQuantity += 1;
            } else if (action === "remove") {
                newQuantity -= 1;
                if (newQuantity < 1) return interaction.reply({ embeds: [new EmbedBuilder().setDescription("❌ | Você não pode diminuir mais.")], ephemeral: true });
            }

            this.quantity = newQuantity;

            // Atualiza o DB
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { quantity: this.quantity },
                { new: true }
            );

            // Atualiza a mensagem
            await interaction.update(this.cratePlanItens());

            // Reinicia o timer de inatividade
            this.setInactivityTimer(() => this.handleInactivity());
        } catch (error) {
            console.error("Erro ao atualizar quantidade do carrinho:", error);
            if (interaction) {
                await interaction.reply({ content: "Erro ao atualizar a quantidade. Tente novamente.", ephemeral: true });
            }
        }
    };

    handleCancellation = async (interaction) => {
        try {
            const logEmbed = new EmbedBuilder()
                .setTitle("Sistema de Logs - Cancelamento")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 Usuário', value: `${this.user.tag} - \`${this.user.id}\`` },
                    { name: '📝 Carrinho', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '🕒 Data', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)` },
                    { name: '❔ Motivo', value: `Cancelado pelo usuário.` }
                );

            await this.sendLog(logEmbed);

            if (this.channel) {
                await Cart.deleteOne({ channelId: this.channel.id });
                await this.channel.delete().catch(e => console.error("Erro ao deletar canal após cancelamento:", e));
            }
        } catch (error) {
            console.error("Erro ao lidar com cancelamento:", error);
        }
    };

    handleCancelPayment = async (interaction) => {
        try {
            const logEmbed = new EmbedBuilder()
                .setTitle("Sistema de Logs - Pagamento Cancelado")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 Usuário', value: `${this.user.tag} - \`${this.user.id}\`` },
                    { name: '📝 Carrinho', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '❔ Motivo', value: `Pagamento cancelado pelo usuário.` },
                    { name: '🕒 Data', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)` }
                );

            await this.sendLog(logEmbed);

            if (this.paymentId) {
                // Tenta cancelar o pagamento antes de limpar o carrinho
                await this.paymentProcessor.cancelPayment(this.paymentId); 
            }

            if (this.channel) {
                await Cart.deleteOne({ channelId: this.channel.id });
                await this.channel.delete().catch(e => console.error("Erro ao deletar canal após cancelamento de pagamento:", e));
            }
        } catch (error) {
            console.error("Erro ao cancelar pagamento:", error);
        }
    };


    // --- FLUXO PRINCIPAL ---

    createCart = async () => {
        try {
            // 1. Verifica carrinho existente
            const existingCart = await Cart.findOne({ userId: this.user.id });
            if (existingCart) {
                const guildChannel = this.client.channels.cache.get(existingCart.channelId);
                if (guildChannel) {
                    this.channel = guildChannel;
                    this.cartId = existingCart.id;
                    this.quantity = existingCart.quantity;
                    this.selectedPlan = existingCart.selectedPlan;

                    // Determina dias com base no plano salvo
                    const planDuration = existingCart.selectedPlan === "mensal" ? 30 : existingCart.selectedPlan === "quizena" ? 15 : 7;
                    this.days = planDuration;

                    return this.interaction ? this.interaction.reply(this.createCartOpenEmbed(guildChannel)) : true;
                }
            }

            await this.interaction.reply({ content: "Aguarde um momento, estou criando seu carrinho...", ephemeral: true });

            // 2. Cria o Thread/Canal
            const thread = await this.interaction.channel.threads.create({
                name: `🛒・${this.user.username}・${this.user.id}`,
                topic: `Carrinho de Compras - ${this.productData.productName} - ${this.cartId}`,
                autoArchiveDuration: 60,
                type: ChannelType.PrivateThread,
                reason: "Criação de carrinho de compras",
                members: [this.user.id],
                permissionOverwrites: [
                    { id: this.user.id, allow: ["ViewChannel"], deny: ["SendMessages"] }, // Permite ver, mas não interage inicialmente
                    { id: this.interaction.guild.id, deny: ["ViewChannel", "SendMessages"] } // Esconde de todos
                ]
            });

            this.channel = thread;

            // 3. Salva no DB
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                {
                    userId: this.user.id,
                    quantity: this.quantity,
                    cartId: this.cartId,
                    productId: this.productId,
                    status: "Aguardando..."
                },
                { upsert: true, new: true }
            );

            // 4. Define o timer e envia mensagem
            this.setInactivityTimer(() => this.handleInactivity());
            await this.interaction.editReply(this.createCartSuccessEmbed(this.channel.url));

            const initialEmbed = this.createPlanSelectionEmbed();
            this.message = await this.channel.send(initialEmbed);

            // 5. Seleciona um plano padrão para iniciar o fluxo
            await this.handlePlanSelection(this.interaction, "30DiasCart"); 
        } catch (error) {
            console.error("Erro fatal ao criar carrinho:", error);
            if (this.interaction) {
                await this.interaction.editReply({ content: "❌ Ocorreu um erro ao iniciar o carrinho. Verifique os logs do bot.", ephemeral: true });
            }
        }
    };

    /**
     * Inicia o processo do carrinho
     */
    run = async () => {
        await this.createCart();

        // Listener para interações dentro do carrinho
        const collector = this.channel.createMessageComponentCollector({ componentType: ComponentType.Button, time: COLLECTION_TIME_MS });

        collector.on("collect", async (btnInteraction) => {
            // Garante que a interação veio do usuário correto
            if (btnInteraction.user.id !== this.user.id) {
                await btnInteraction.deferUpdate();
                return;
            }

            clearTimeout(this.inactivityTimer);
            this.interaction = btnInteraction; // Atualiza a referência de interação

            // Reinicia o timer em todas as interações válidas
            this.setInactivityTimer(() => this.handleInactivity());

            try {
                switch (btnInteraction.customId) {
                    case "7DiasCart":
                    case "15DiasCart":
                    case "30DiasCart":
                        await btnInteraction.deferUpdate();
                        await this.handlePlanSelection(btnInteraction);
                        break;

                    case "cancelOrder":
                        await this.handleCancellation(btnInteraction);
                        break;

                    case "addToCart":
                        await this.updateCartQuantity(btnInteraction, "add");
                        break;

                    case "removeFromCart":
                        await this.updateCartQuantity(btnInteraction, "remove");
                        break;

                    case "finalizePurchase":
                        await this.finalizePurchase(btnInteraction);
                        break;

                    case "pixCopyPaste":
                    case "qrCode":
                        await this.sendPaymentDetails(btnInteraction);
                        break;

                    case "cancelPayment":
                        await this.handleCancelPayment(btnInteraction);
                        break;

                    default:
                        console.log(`Custom ID desconhecido: ${btnInteraction.customId}`);
                }
            } catch (e) {
                console.error(`Erro durante a coleta de interação (${btnInteraction.customId}):`, e);
                if (btnInteraction.replied || btnInteraction.deferred) {
                    await btnInteraction.followUp({ content: "⚠️ Ocorreu um erro ao processar esta ação. Tente novamente.", ephemeral: true });
                } else {
                    await btnInteraction.reply({ content: "⚠️ Ocorreu um erro ao processar esta ação. Tente novamente.", ephemeral: true });
                }
            }
        });

        collector.on("end", () => {
            if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
            console.log("Colecionador de interações do carrinho finalizado.");
        });
    };

    /**
     * Função auxiliar para obter e enviar detalhes de pagamento
     */
    async sendPaymentDetails = async (interaction) => {
        try {
            const cart = await Cart.findOne({ channelId: this.channel.id });
            if (cart && cart.paymentId) {
                const paymentDetails = await this.paymentProcessor.getPayment(cart.paymentId);

                if (!paymentDetails) {
                    await interaction.reply({ content: "Detalhes de pagamento não encontrados.", ephemeral: true });
                    return;
                }

                if (interaction.customId === "qrCode" && paymentDetails.attachment) {
                    await interaction.reply({ files: [paymentDetails.attachment], ephemeral: true });
                } else if (interaction.customId === "pixCopyPaste" && paymentDetails.pixCopyPasteCode) {
                    await interaction.reply({ content: paymentDetails.pixCopyPasteCode, ephemeral: true });
                } else {
                     await interaction.reply({ content: "Detalhes de pagamento incompletos.", ephemeral: true });
                }
            } else {
                await interaction.reply({ content: "Pagamento não iniciado ou não encontrado.", ephemeral: true });
            }
        } catch (error) {
            console.error("Erro ao enviar detalhes do pagamento:", error);
            await interaction.reply({ content: "Ocorreu um erro ao obter os detalhes do pagamento. Tente mais tarde.", ephemeral: true });
        }
    };
}

module.exports = CartClass;
